import{_ as t,o as r,c as n,a2 as s}from"./chunks/framework.B2QVIpOM.js";const d=JSON.parse('{"title":"拔萃女书院 · 年份未注明 · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"school-5234a481","school_zh":"拔萃女书院","school_en":"—","grade":"s1","year":"unknown","year_label":"年份未注明","type":"interview","title":"拔萃女书院 · 年份未注明 · 中一 · 面试","anonymous":true,"source_ids":["C1821-DGS-U","GUIDE-DGS","HOT22-DGS"],"rounds":["unknown","r1","r2"]},"headers":[],"relativePath":"reports/school-5234a481/s1/unknown-interview.md","filePath":"reports/school-5234a481/s1/unknown-interview.md"}'),p={name:"reports/school-5234a481/s1/unknown-interview.md"};function e(l,o,a,g,i,c){return r(),n("div",null,[...o[0]||(o[0]=[s('<h1 id="拔萃女书院-·-年份未注明-·-中一-·-面试" tabindex="-1">拔萃女书院 · 年份未注明 · 中一 · 面试 <a class="header-anchor" href="#拔萃女书院-·-年份未注明-·-中一-·-面试" aria-label="Permalink to &quot;拔萃女书院 · 年份未注明 · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/school-5234a481">← 返回拔萃女书院资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-c1821-dgs-u" tabindex="-1">资料来源：【其它机构】升中面试经验汇总_18-21.pdf <a class="header-anchor" href="#record-c1821-dgs-u" aria-label="Permalink to &quot;资料来源：【其它机构】升中面试经验汇总_18-21.pdf {#record-c1821-dgs-u}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>英语：</strong> 英语</p><p><strong>阅读与活动讨论</strong></p><p>朗读文章，约5分钟讨论学校暑期活动，在资讯科技和马戏团等活动中选择；另有露营讨论。</p><p><strong>个人与校长会面</strong></p><p>是否参加其他学校面试、想入哪所及原因，现今儿童是否有自由玩耍，同一作品的书与电影有什么不同。有考生与父母一起进校长室，先介绍父母，再请父母到外等候。</p></blockquote><blockquote><p><strong>语文：</strong> 中文（口语未注明）</p><p><strong>文言朗读、理解与生活例子</strong></p><p>朗读“以铜为镜”“以古为镜”“以人为镜”相关文字，解释含义，并举生活例子说明如何以别人作为镜鉴；另有文言理解及创意表达。</p></blockquote><blockquote><p><strong>数学：</strong> 英语</p><p><strong>速算题量及时间差异</strong></p><p>iPad口答，一组限2分钟，不会可说Skip；另有题本20题、3分钟、可不按次序作答；还有2分钟面对60题的反馈。不同题量与计时不合并成同一套固定要求。</p></blockquote><h2 id="record-guide-dgs" tabindex="-1">资料来源：女拔面試題.pdf <a class="header-anchor" href="#record-guide-dgs" aria-label="Permalink to &quot;资料来源：女拔面試題.pdf {#record-guide-dgs}&quot;">​</a></h2><p><strong>资料类型：</strong> 机构整理：历年面试题型</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第一轮-·-原文明示" tabindex="-1">第一轮 · 原文明示 <a class="header-anchor" href="#第一轮-·-原文明示" aria-label="Permalink to &quot;第一轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>语文：</strong> 粤语或普通话</p><p><strong>阅读、文言与个人分享</strong></p><ul><li>朗读并概括文章主要意思，部分任务限时1分钟。</li><li>阅读两句文言文并回答2题；另有阅读一段文言文后回答1题的形式。</li><li>分享孝顺家人的经历、最喜欢的书，并讨论教育的重要性。</li><li>阅读关于成功源于努力而非天赋的文章，再联系自己的成功经历。</li><li>阅读有关古代学者学习观念的文字，再以「学习最重要具备什么条件」作1分钟短讲。</li></ul></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>朗读与小组讨论</strong></p><p>朗读任务约1分钟，可能遇到较难词汇。小组讨论题目包括：</p><ul><li>如何安排学校家庭日？</li><li>怎样推动学习和阅读？</li><li>为弱势群体选择什么圣诞礼物？</li><li>学校应增加哪些活动或设施？</li><li>最感谢谁，如何表达谢意？</li><li>怎样安排夏令营？</li><li>孩子适合在什么年龄拥有手机？</li></ul></blockquote><blockquote><p><strong>数学：</strong> 英语</p><p><strong>限时心算的不同形式</strong></p><p>其中一种形式为1分钟完成2道奥数题；另一种为约4至5分钟完成20题，涵盖整数、分数、小数四则运算及立体图形。20题的形式包括10题平板作答和10题英文口头提问，不能将这些变体合并为同一套固定题量。</p></blockquote><blockquote><p><strong>互动任务：</strong> 未注明</p><p><strong>设计任务</strong></p><p>设计学校徽章。</p></blockquote><h3 id="第二轮-·-原文明示" tabindex="-1">第二轮 · 原文明示 <a class="header-anchor" href="#第二轮-·-原文明示" aria-label="Permalink to &quot;第二轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>英语：</strong> 英语</p><p><strong>个人经历与学习选择</strong></p><ul><li>自我介绍，回顾第一轮最困难的任务。</li><li>为什么选择拔萃女书院？还申请了哪些学校？</li><li>参加哪些运动或音乐活动，为什么热衷这些活动？</li><li>小学阶段最难的科目是什么？</li><li>昨晚有没有读报？</li><li>喜欢什么类型的书、如何学习、将来希望从事什么职业？</li></ul></blockquote><blockquote><p><strong>语文：</strong> 普通话</p><p><strong>生活安排与升学计划</strong></p><p>讨论休息及玩耍时间是否充足、香港学生是否有足够时间玩耍；说明每日运动时间和地点。其他问题包括选择女校的原因、父母职业、理想职业、未来升学计划，以及有没有朋友已在该校就读。</p></blockquote><blockquote><p><strong>家长面谈：</strong> 未注明</p><p><strong>亲子共同环节</strong></p><p>学生向老师介绍父母。老师可能询问家长：如果平日这个时间应在工作，今天如何向雇主说明安排？部分环节会请家长先到外面等候，再与学生单独交流。</p></blockquote><h2 id="record-hot22-dgs" tabindex="-1">资料来源：热门港校面试真题集：中学篇.pdf <a class="header-anchor" href="#record-hot22-dgs" aria-label="Permalink to &quot;资料来源：热门港校面试真题集：中学篇.pdf {#record-hot22-dgs}&quot;">​</a></h2><p><strong>资料类型：</strong> 2022/23机构汇编中的历史面试题</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第一轮-·-原文明示-1" tabindex="-1">第一轮 · 原文明示 <a class="header-anchor" href="#第一轮-·-原文明示-1" aria-label="Permalink to &quot;第一轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>语文：</strong> 粤语／普通话</p><p><strong>阅读与理解</strong></p><p>朗读文章后用约一分钟概括主要讯息；也有朗读两句古语并回答两题、朗读文言文后回答一题的形式。</p><p><strong>个人经验与观点</strong></p><p>分享孝顺父母的经历，说明教育是否重要；阅读“成功靠努力而非天赋”的文章后，分享自己成功的经验。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>朗读</strong></p><p>一分钟内朗读文章，遇到较难词汇也需尝试读出。</p></blockquote><blockquote><p><strong>数学：</strong> 英语</p><p><strong>限时心算的不同形式</strong></p><p>一种为一分钟内完成两道奥数式心算题；另一种为五分钟20题，其中10题以iPad作答，另10题口头回答。题型涉及分数、小数与整数四则运算，以及立体图形。</p></blockquote><blockquote><p><strong>综合能力：</strong> 语言未注明</p><p><strong>校章绘画</strong></p><p>重新绘画一个校章。</p></blockquote><blockquote><p><strong>小组讨论：</strong> 英语</p><p><strong>时间与形式</strong></p><p>讨论约4至5分钟，外籍老师在旁观察。</p><p><strong>校园与关怀</strong></p><p>设计学校家庭日活动；如何鼓励学生多学习、多阅读；圣诞节送什么给贫困儿童；学校应增加哪些活动或设施。</p><p><strong>生活与成长</strong></p><p>感激谁及如何表达；夏令营做什么；儿童何时应拥有自己的手机。</p></blockquote><h3 id="第二轮-·-原文明示-1" tabindex="-1">第二轮 · 原文明示 <a class="header-anchor" href="#第二轮-·-原文明示-1" aria-label="Permalink to &quot;第二轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>英语：</strong> 英语</p><p><strong>自我认识与学习</strong></p><p>自我介绍；首轮最难的部分；为何选择女拔；喜欢什么运动或音乐及投入原因；小学最难学科；学习技巧；未来志向。</p><p><strong>阅读与申请</strong></p><p>还申请哪些学校；昨晚是否看报；喜欢什么类型的书。</p></blockquote><blockquote><p><strong>语文：</strong> 普通话</p><p><strong>休息与活动</strong></p><p>是否有休息或玩耍时间、香港学生是否有足够玩耍时间；每天运动多久、在哪里运动；为何申请的都是女校。</p></blockquote><blockquote><p><strong>亲子环节：</strong> 语言未注明</p><p><strong>介绍家长与情境沟通</strong></p><p>与父母一同进入面试室，介绍父母；说明父母本应工作时如何向主管交代陪同安排；按要求请父母到室外等候。</p></blockquote>',38)])])}const h=t(p,[["render",e]]);export{d as __pageData,h as default};
